    val MAP: Map<String, DuaText> = mapOf(
        "dua_travel_full" to DuaText("पुराय प्रवासाची विनवणी", "हे अल्लाह, ह्या प्रवासांत आमी तुका धर्म आनी धर्मनिश्ठे खातीर, आनी तुका प्रसन्न करपी कामां खातीर मागतात. हे अल्लाह, आमच्यासाठी हो प्रवास सोंपो कर आनी ताचें अंतर उणें कर. हे अल्लाह, तूं प्रवासांतलो साथीदार आनी कुटुंबाचो राखणदार.", "प्रवासाक भायर सरतना,'सुभानल्लधी सखारा \"उपरांत.", "पुराय सुन्नत प्रवास दुआ."),
        "dua_return_travel" to DuaText("प्रवासांतल्यान परत येवप", "आमी परत येतात, पश्चात्ताप करतात, आमच्या प्रभूची पुजा करतात आनी तोखणाय करतात.", "प्रवासांतल्यान परततकच.", "पयशांनी प्रवासांतल्यान परततना हें सांगलें."),
        "dua_farewell_traveller" to DuaText("भोंवडेकाराक निरोप दिवपाची बोली", "हांव तुमचो धर्म, तुमचो विस्वास आनी तुमच्या कृतींचो परिणाम अल्लाहाक सोंपयता.", "जेन्ना भोंवडेकाराक निरोप दितात.", "अल्लाहाक जें सोंपलां तें केन्नाच ना जाता."),
        "dua_entering_town" to DuaText("एका सुवातेर थांबप", "ताणें निर्माण केल्ल्या सगळ्या वायट गजालीं पसून हांव अल्लाहच्या परिपूर्ण उतरांचो आलाशिरो मागता.", "खंयच्याय सुवातेर थांबतना वा नव्या शारांत पावतकच.", "तो थंयच्यान वता मेरेन ताका कांयच लुकसाण जायना."),
        "dua_boarding_ship" to DuaText("तारवांचेर/वाहनांत चडप", "अल्लाहच्या नांवान ताची नौकाविहार आनी तें लांकडी आसा. खरें म्हणल्यार म्हजो प्रभू क्षमाशील, दयाळू आसा.", "तारवांचेर वा वाहनांत चडतना-पैगंबर नूह (अ. स.) हाचे उतर.", "कुराणांतलें एक श्लोक-नूहाच्या (ए. एस.) सन्दुकाचें दुआ."),
        "dua_istighfar_hayyul_qayyum" to DuaText("हयुल-कयूम हांचे वांगडा इस्तिघफर", "हांव अल्लाहाकडेन माफी मागता, ताचे भायर देव ना, सदासर्वकाळ जगपी, पालन करपी, आनी हांव पश्चात्ताप करून ताचे कडेन वळता.", "पश्चात्तापा खातीर.", "तो झुजाच्या मैदानांतल्यान पळून गेलो तरी ताच्या पापांची माफी मेळटा."),
        "dua_rabbighfir_warham" to DuaText("रब्बीघफिर वारहम", "म्हज्या देवा, माफ कर आनी दया कर, कारण तूं दया दाखोवप्यां मदीं सगळ्यांत बरो.", "कुराणांतली दुआ-क्षमा आनी दये खातीर.", "सूरह अल-मु'मिनूनाचे निमाणें श्लोक."),
        "dua_majlis_kaffarah" to DuaText("कफरत अल-मज्लीस", "हे अल्लाह, तुका गौरव आनी तोखणाय. तूं सोडून देव ना हाची हांव साक्षी दिता. हांव तुझी क्षमा मागता आनी पश्चात्ताप करून तुजे कडेन वळता.", "जमनीतल्यान उठतना.", "जमनींत जें कितें चुकीचें उलयलें ताचे खातीर ती प्रायश्चित्त जाता."),
        "dua_jami_forgiveness" to DuaText("व्यापक क्षमा", "हे अल्लाह, म्हज्या चुकांक, म्हज्या अज्ञानाक, म्हज्या बाबतींत म्हज्या अतिभावाक, आनी तूं म्हजे परस चड जाणा आसा तें सगळें म्हाका माफ कर.", "पैगंबर सल्ल्याह अलियाह वसलमाचो एक व्यापक दुआ.", "पैगंबर सल्ल्याह अलियाह वसलम ही दुआ करताले."),
        "dua_parents_nuh" to DuaText("आवय-बापाय खातीर नूह (ए. एस.) ची दुआ", "म्हज्या देवा, म्हज्या आवय-बापायक, जो कोण म्हज्या घरांत विश्वासीक म्हणून प्रवेश करता, आनी सगळ्या विश्वासू दादल्यांक आनी बायलांक माफ कर.", "आपल्या आवय-बापाय खातीर आनी आस्तीक लोकां खातीर.", "पैगंबर नूह (अ. स.) हाचें दुआ."),
        "dua_shukr_parents" to DuaText("आवय-बापूय आनी धर्मीक भुरग्यांखातीर उपकार", "म्हज्या प्रभू, तूं म्हाका आनी म्हज्या आवय-बापायक दिल्ल्या उपकारा खातीर म्हाका उपकार मानपाक, आनी तुका प्रसन्न करपी धर्मीक कामां करपाक, आनी म्हजी संतती धर्मीक करपाक. हांव पश्चात्तापान तुजे कडेन वळता आनी हांव शरण येवप्यां मदीं आसा.", "चाळीस वर्सां पिरायेचेर पावपाचो कुराण दुआ.", "उपकार, बरी कामां आनी आपल्या भुरग्यांची धर्मीकताय-सगळें एकाच दुआत."),
        "dua_intimacy" to DuaText("लग्न संबंदां पयलीं", "अल्लाहच्या नांवान. हे अल्लाह, शयतान आमचे पसून पयस दवर आनी तूं आमकां जें (भुरगीं) दिता ताचे पसून शयतान पयस दवर.", "लग्न संबंदां पयलीं.", "भुरग्याक निर्णय दिल्यार शयतान ताका केन्नाच लुकसाण करचो ना."),
        "dua_ibrahim_children_protection" to DuaText("घर आनी भुरग्यांची राखण", "म्हज्या देवा, हें शार सुरक्षीत कर आनी म्हाका आनी म्हज्या भुरग्यांक मुर्तींची पुजा करचे पसून पयस दवर.", "पैगंबर इब्राहिम (अ. स.) हाचें दुआ-शार आनी ताच्या भुरग्यांच्या सुरक्षे खातीर.", "तौहीदाचेर ठाम रावपा खातीर दुआ."),
        "dua_drinking_milk" to DuaText("दूद पिवतना", "हे अल्लाह, ताका आमचे खातीर आशीर्वाद दिवचो आनी ताका चड दिवचो.", "दूद पिवतना.", "जेवण आनी पेय ह्या दोनूय बाबतींत दूद फावोशें आसता."),
        "dua_iftar_host" to DuaText("हेरां वांगडा उपास सोडतना", "उपवास करपी लोक तुज्या वांगडा आपलो उपवास मोडूंक जाय, धर्मीक तुमचें जेवण खावंक जाय, आनी देवदूतां तुज्या खातीर प्रार्थना करूंक जाय.", "कोणाकूय घरांत उपोषण मोडतना.", "यजमाना खातीर पैगंबरांचे सल्ल्याह अलियाह वसलम दुआ."),
        "dua_seeing_first_fruit" to DuaText("पयलें फळ पळय", "हे अल्लाह, आमच्या फळांक आशीर्वाद दिवचो, आमच्या शारांत आमकां आशीर्वाद दिवचो, आनी आमच्या सा'आनी आमच्या मडांत (माप) आमकां आशीर्वाद दिवचो.", "हंगामाचें पयलें फळ पळोवन.", "उदरनिर्वाहांत आनी आपल्या शारांत आशीर्वाद मेळोवपा खातीर एक दुआ."),
        "dua_good_news" to DuaText("मनभुलयण्या बातम्यांचेर", "सगळ्यो तोखणाय अल्लाहाक जाता, जाचे उपकारान बरे काम पुराय जातात.", "बरी खबर मेळ्ळ्या उपरांत (आनी उपकार मानून नमस्त).", "पैगंबर सल्ल्यल्लाह अलीह वसलमान ताका आवडपी कितें तरी पळोवन हें सांगलें."),
        "dua_looking_mirror" to DuaText("आरशांत पळय", "हे अल्लाह, जशें तूं म्हजो देखाव बरो केला, म्हजें पात्रूय बरें कर.", "हारशांत पळयतना.", "पैगंबर सल्ल्याह अलियाह वस्लमान ही दुआ केली (हारश्याचो उल्लेख करिनासतना लेगीत ती स्थापन जाल्या)."),
        "dua_rabbana_taqabbal" to DuaText("कृती मान्य करप", "हे म्हज्या प्रभू, आमचे कडल्यान हें स्वीकार. तूं खरें म्हणल्यार सगळो आयकपी, सगळो जाणकार. आनी आमचो पश्चात्ताप मान्य कर. खरें म्हणल्यार तूं पश्चात्ताप करपी, दयाळू.", "इब्राहिम आनी इस्मायील (ए. एस.) हांणी काबा बांदतना विचारलें.", "दरेक बरे कारणा उपरांत मान्यताय मेळोवपा खातीर दुआ."),
        "dua_muawwidhat" to DuaText("तीन कुल (मुआववाद)", "(सूरह-उल-इखलास) म्हणः तो एकूच अल्लाह. अल्लाह, स्वयंपूर्ण. तो जल्माक येवंक ना वा जल्माक येवंक ना. आनी ताचे कडेन तुलना करपाक कोणूच ना.\n\n(सुरा अल-तलाक) म्हणः हांव सकाळच्या प्रभू कडेन, ताणें निर्माण केल्ल्या वायट गजालीं पसून, तें स्थीत जातकच काळोखाच्या वायट गजालींतल्यान, गांठी उडयल्ल्यांच्या वायट गजालींतल्यान आनी ईर्ष्या करपी जेन्ना ईर्ष्या करता तेन्ना ताच्या वायट गजालींतल्यान आलाशिरो मागता.\n\n(सूरह-नास) म्हणः हांव मानवजातीचो प्रभू, मनशाचो राजा, मनशाचो देव, जिन आनी मनशाच्या मनशांतल्यान मनशाच्या काळजांत कुजबुजपी फाटीं सरपी कुजबुज करपीच्या वायटपणा पसून आलाशिरो मागता.", "तीन सूरह सकाळीं आनी सांजीं तीन फावटीं, आनी न्हिदचे पयलीं, हातांत उडयतात आनी कुडीचेर पुसतात.", "सकाळीं आनी सांजीं तीन फावटीं ताचो पठण करप सगळ्यां आड फावोशें."),
        "dua_sabr" to DuaText("धीर आनी स्थैर्य हांचे खातीर", "म्हज्या देवा, आमचेर धीर दवर, आमचे पांय घटमूट कर आनी अविश्वास करपी लोकां आड आमची मदत कर.", "कश्ट आनी झगड्याच्या वेळार.", "तालूतच्या सैन्याचो दुआ."),
        "dua_rabbana_innana_amanna" to DuaText("क्षमा आनी उज्यां पसून राखण", "म्हज्या देवा, आमी विश्वास दवरला, देखून आमचे पापां माफ कर आनी उज्याच्या ख्यास्तेकडल्यान आमची राखण कर.", "कुराणची दुआ.", "देवभयरांच्या गुणां मदीं एक दुआचो उल्लेख आसा."),
        "dua_rabbana_hab_lana_rahmah" to DuaText("आमच्या बाबतींत मार्गदर्शन (आशाब अल-कहफ)", "म्हज्या देवा, तुजी दया करून आमचेर दया कर आनी आमच्या बाबतींत आमचे खातीर योग्य मार्गदर्शन तयार कर.", "द दुआ ऑफ द पीपल ऑफ द लेव्ह.", "निर्णय घेवप आनी कठीण परिस्थितींत मार्गदर्शन करप."),
        "dua_musa_faqir" to DuaText("मुस (ए. एस.) हाचो दुआ तरतुदी खातीर", "म्हज्या देवा, तूं म्हाका जें बरें धाडटा तें म्हाका खरेंच जाय आसा.", "पुरवण आनी बरें सोदप-मदयांत मुसा (ए. एस.) हाचें दुआ.", "ह्या दुआ उपरांत अल्लाहान मूसाक (अ. स.) घर, काम आनी बायल दिली."),
        "dua_ayyub" to DuaText("आयूब (ए. एस.) हाचो दुआ दुयेंत", "(म्हज्या प्रभू,) दुख्खान म्हाका स्पर्श केला, आनी तूं दयाळू लोकां मदीं परम दयाळू आसा.", "दुयेंस आनी दुख्खीपणांत.", "अल्लाहान अयूब (अ. स.) हाचें दुख्ख पयस केलें."),
        "dua_husn_khatimah" to DuaText("मुसलमान म्हूण मर \"(युसूफ ए. एस.)", "स्वर्ग आनी धर्तरेचो निर्मातो, तूं ह्या संवसारांत आनी आख़िरतांत म्हजो राखणदार. म्हाका मुसलमान म्हूण मरपाक लाय आनी धर्मीकां वांगडा म्हजे वांगडा मेळ.", "एका बरो शेवट करपा खातीर एक दुआ.", "पैगंबर युसूफाची दुआ."),
        "dua_shaitan_hamazat" to DuaText("शेतानांच्या व्हिस्परा पसून आश्रय", "म्हज्या प्रभू, भुतांच्या कुजबुजांतल्यान हांव तुका आलाशिरो मागता, आनी म्हज्या प्रभू, ते म्हज्या लागीं येचे न्हय म्हणून हांव तुका आलाशिरो मागता.", "सैतानाच्या कुजबुज्यां पसून शरण घे.", "आलाशिरो घेवपाची कुराणची दुआ."),
        "dua_bad_character" to DuaText("वायट चारित्र्याक शरण", "हे अल्लाह, हांव तुज्या कडेन वायट स्वभाव, वायट कामां आनी वायट इत्सा हांचे पसून आलाशिरो मागता.", "वायट चारित्र्य, कृती आनी इत्सा हांचे पसून शरण घे.", "पैगंबर सल्ल्याह अलियाह वसलमा कडल्यान आलाशिरो घेवपाचो दुआ."),
        "dua_zawal_nimah" to DuaText("आशीर्वाद ना जावपा पसून शरण", "हे अल्लाह, तुज्या आशीर्वादाच्या लुकसाणांतल्यान, तुज्या कल्याणांत बदल जाल्ल्यान, तुज्या अचकीत ख्यास्तीन आनी तुज्या सगळ्या रागांतल्यान हांव तुजो आलाशिरो मागता.", "आशीर्वाद वगडावपा पसून आनी अचकीत संकटा पसून शरण घेवचें.", "पैगंबर सल्ल्याह अलियाह वसलमाचो एक दुआ."),
        "dua_useless_knowledge" to DuaText("फायद्या विरयत गिन्यानांतल्यान शरण", "हे अल्लाह, फायदो जायना त्या गिन्यानांतल्यान, भियेना त्या काळजांतल्यान, केन्नाच तृप्त जायना त्या आत्म्याकडल्यान आनी जाप मेळना त्या दुआकडल्यान हांव तुका आलाशिरो मागता.", "निरर्थक गिन्यान आनी अल्लाहाक भियेनासतना काळजा पसून शरण घे.", "पैगंबर सल्ल्याह अलियाह वसलमा कडल्यान आलाशिरो घेवपाचो दुआ."),
        "dua_beneficial_knowledge" to DuaText("फायद्याचें गिन्यान आनी हलाल रिझक", "हे अल्लाह, हांव तुका फायद्याचें गिन्यान, शुद्ध उदरगत आनी मान्यताय मेळयल्ल्यो कृती मागता.", "फजर प्रार्थने उपरांत.", "पैगंबर सल्ल्याह अलियाह वसलमान फजरच्या सलमा उपरांत हें सांगलें."),
        "dua_leprosy_diseases" to DuaText("गंभीर दुयेंसां पसून शरण घेवप", "हे अल्लाह, हांव कोड, वेडेपण, कुश्टरोग आनी सगळ्या वायट दुयेंसां पसून तुका आलाशिरो मागता.", "गंभीर दुयेंसां पसून राखण.", "भलायकी राखपा खातीर सुन्नत दुआ."),
        "dua_fear_people" to DuaText("दुस्मान वा अत्याचारी हांचो भंय", "हे अल्लाह, आमी तुका तांचे मुखार दवरतात आनी तांच्या वायटपणासावन तुका आलाशिरो दितात.", "जेन्ना लोकांक वा मनशाक लुकसाण जावपाची भंय आसता.", "पैगंबर सल्ल्याह अलियाह वसलमान लोकांक भियेवतना हें सांगलें."),
        "dua_shirk_protection" to DuaText("लपलेल्या शिर्कावयल्यान संरक्षण", "हे अल्लाह, हांव तुका कितेंय कळून सांगपाक तुका आलाशिरो मागता, आनी हांव अजाण्यान जे करता ताचे खातीर हांव तुका क्षमा मागता.", "दाखोवपा पसून आनी लिपून दवरपा पसून सुरक्षीत रावपाक.", "मुंग्या रेंवपा परस लुकोवन दवरिल्लो शिर्क चड लुकोवन दवरतात."),
        "dua_rain" to DuaText("जेन्ना पावस पडटा", "हे अल्लाह, (धाड) फायद्याचो पावस.", "जेन्ना पावस पडटा.", "पावस हो एक वेळ जेन्ना दुआ मान्य करतात."),
        "dua_after_rain" to DuaText("पावसा उपरांत", "अल्लाहच्या कृपेन आनी ताच्या दयेन आमकां पावस पडिल्लो.", "पावसा उपरांत.", "जो अशें म्हणटा तो अल्लाहाक मानपी."),
        "dua_istisqa" to DuaText("पावस मागप (इस्तिस्का)", "हे अल्लाह, आमकां पावस (तीन फावटीं) धाड.", "जेन्ना पावस पडना.", "पैगंबर सल्ल्याह अलियाह वसलमान शुक्राराच्या उपदेशांत ही दुआ केली आनी पावस पडलो."),
        "dua_heavy_rain" to DuaText("चड पावस पडप", "हे अल्लाह, (पडूंक दिवचो) आमच्या भोंवतणी आनी आमचेर न्हय.", "जेन्ना खूब पावस पडटा.", "पैगंबर सल्लल्लाह अलियाह वसलमाच्या दुआतल्यान ढग पयस गेले."),
        "dua_wind" to DuaText("जेन्ना वारें व्हांवता", "हे अल्लाह, हांव तुका ताचे बरे, तातूंतले बरे आनी जें ताचे वांगडा धाडिल्लें ताचे बरे खातीर मागता, आनी हांव तुका ताचे वायट, तातूंतले वायट आनी जें ताचे वांगडा धाडिल्लें वायट हांचे पसून आलाशिरो मागता.", "जेन्ना खर वारें वा वादळ येता.", "पैगंबर सल्ल्याह अलियाह वसलमान वादळांच्या वेळार ही दुआ केली."),
        "dua_thunder" to DuaText("गर्जना आयकुपाक", "गर्जना ताच्या तोखणायेन जांचो तोखणाय करता, आनी देवदूतांचो ताच्या भंयान तो गौरव असो.", "गर्जना आयकून-अब्दुल्ला इब्न अझ-जुबैर (आर. ए.) हाचो सराव.", "सूरह अर-राद (13:13) हाचे वयल्यान घेतिल्लें."),
    )
}
